import CryptoKit
import Foundation
@testable import RagdollCore

struct ReportSettings: Decodable {
    let excludedProjects: Set<String>
    let prices: [String: Price]
}

func failure(_ message: String) -> NSError {
    NSError(domain: "Ragdoll.Report", code: 1, userInfo: [NSLocalizedDescriptionKey: message])
}

func git(_ arguments: [String], at repository: URL) throws -> Data {
    let process = Process()
    process.executableURL = URL(fileURLWithPath: "/usr/bin/git")
    process.arguments = ["-C", repository.path] + arguments
    let pipe = Pipe()
    process.standardOutput = pipe
    try process.run()
    let data = pipe.fileHandleForReading.readDataToEndOfFile()
    process.waitUntilExit()
    guard process.terminationStatus == 0 else { throw failure("Git 操作失败：\(arguments[0])") }
    return data
}

func text(_ data: Data) -> String {
    String(decoding: data, as: UTF8.self).trimmingCharacters(in: .whitespacesAndNewlines)
}

func hash(_ data: Data) -> String {
    SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
}

func run() throws {
    let arguments = CommandLine.arguments
    guard arguments.count == 5, ["preview", "publish"].contains(arguments[1]) else { throw failure("参数无效") }
    let publish = arguments[1] == "publish"
    let repository = URL(fileURLWithPath: arguments[2], isDirectory: true)
    let output = publish ? repository : URL(fileURLWithPath: arguments[4], isDirectory: true)
    let lease = publish ? try ServiceLease(root: repository, name: ".ragdoll-archive-lock") : nil
    defer { withExtendedLifetime(lease) {} }
    let destination = "https://github.com/OyamaMeek/Ragdoll_sync.git"
    let branch = "refs/heads/main"
    let remoteRef = try text(git(["ls-remote", destination, branch], at: repository)).split(whereSeparator: \.isWhitespace)
    let base = try text(git(["rev-parse", "HEAD"], at: repository))
    guard remoteRef.count == 2, remoteRef[0] == base, remoteRef[1] == branch,
          try text(git(["symbolic-ref", "HEAD"], at: repository)) == branch,
          try text(git(["remote", "get-url", "--push", "--all", "origin"], at: repository)) == destination,
          try git(["status", "--porcelain=v1", "--untracked-files=no"], at: repository).isEmpty else {
        throw failure("本地工作区或归档分支与 GitHub 上的提交不一致")
    }

    let decoder = JSONDecoder()
    let settings = try decoder.decode(ReportSettings.self, from: Data(contentsOf: URL(fileURLWithPath: arguments[3])))
    let tracked = try git(["ls-tree", "-rz", "--name-only", base, "--", "sessions"], at: repository)
    let paths = Set(tracked.split(separator: 0).map { String(decoding: $0, as: UTF8.self) })
    let archived = try paths.filter { $0.hasSuffix("/metadata.json") }.sorted().map { path in
        let session = try decoder.decode(Session.self, from: Data(contentsOf: repository.appendingPathComponent(path)))
        let archivedPath = Archive.sessionPath(session)
        guard path == archivedPath + "/metadata.json", paths.contains(archivedPath + "/transcript.md") else { throw failure("归档会话路径不一致") }
        return session
    }
    guard !archived.isEmpty else { throw failure("找不到已提交的归档会话") }
    let sessions = archived.filter { !settings.excludedProjects.contains($0.project) }
    let readme = ArchiveActivity.readmePath
    let chart = ArchiveActivity.chartPath
    let manifest = ArchiveActivity.manifestPath
    let names = [readme, chart, manifest]
    let status = try git(["status", "--porcelain=v1", "--untracked-files=all", "--ignored=matching", "--"] + names, at: repository)
    guard status.isEmpty, try git(["ls-files", "--"] + names, at: repository).isEmpty else { throw failure("归档报告文件已存在") }
    let activity = ArchiveActivity.render(sessions, prices: settings.prices)
    let activityManifest = [readme: hash(activity.section), chart: hash(activity.chart), ArchiveActivity.sectionKey: hash(activity.section)]
    let encoder = JSONEncoder()
    encoder.outputFormatting = [.prettyPrinted, .sortedKeys, .withoutEscapingSlashes]
    for (name, data) in [(readme, activity.section), (chart, activity.chart), (manifest, try encoder.encode(activityManifest))] {
        try data.write(to: output.appendingPathComponent(name), options: .withoutOverwriting)
    }
    if publish {
        let literals = names.map { ":(top,literal)\($0)" }
        _ = try git(["add", "--"] + literals, at: repository)
        _ = try git(["commit", "--only", "-m", "docs(archive): publish activity README", "--"] + literals, at: repository)
        let diff = try text(git(["diff", "--name-only", base, "HEAD"], at: repository))
        guard Set(diff.split(separator: "\n").map(String.init)) == Set(names) else { throw failure("提交包含额外文件") }
        print("commit=\(try text(git(["rev-parse", "HEAD"], at: repository)))")
        _ = try git(["push", "origin", "HEAD:\(branch)"], at: repository)
    }
    print("archived=\(archived.count) reported=\(sessions.count)")
}

do { try run() }
catch {
    FileHandle.standardError.write(Data((error.localizedDescription + "\n").utf8))
    exit(1)
}

